<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Aquarium Screensaver</title>
    <style>
        html, body {
            margin: 0;
            overflow: hidden;
            background: #000;
        }
        canvas {
            display: block;
        }
    </style>
</head>
<body>
<canvas></canvas>
<script>
    const canvas = document.querySelector('canvas');
    const ctx = canvas.getContext('2d');
    let width, height;
    let lastTime = 0;

    function resize() {
        width = window.innerWidth;
        height = window.innerHeight;
        canvas.width = width;
        canvas.height = height;
    }
    window.addEventListener('resize', resize);
    resize();

    // Gradient background
    const gradient = ctx.createLinearGradient(0, 0, 0, height);
    gradient.addColorStop(0, '#001f4d');
    gradient.addColorStop(1, '#003366');

    // Fish class
    class Fish {
        constructor() {
            this.size = Math.random() * 20 + 10;
            this.x = Math.random() * width;
            this.y = Math.random() * height;
            this.vx = (Math.random() - 0.5) * 2;
            this.vy = (Math.random() - 0.5) * 2;
            this.color = `hsl(${Math.random() * 360}, 100%, 60%)`;
            this.direction = Math.random() > 0.5 ? 1 : -1;
            this.tailAngle = Math.random() * Math.PI * 2;
        }

        update() {
            this.x += this.vx * this.size;
            this.y += this.vy * this.size;

            // Edge collision
            if (this.x < 0 || this.x > width) {
                this.vx *= -1;
                this.x = Math.max(0, Math.min(width, this.x));
            }
            if (this.y < 0 || this.y > height) {
                this.vy *= -1;
                this.y = Math.max(0, Math.min(height, this.y));
            }
        }

        draw() {
            ctx.save();
            ctx.translate(this.x, this.y);
            ctx.rotate(this.tailAngle);

            // Body
            ctx.beginPath();
            ctx.arc(0, 0, this.size, 0, Math.PI * 2);
            ctx.fillStyle = this.color;
            ctx.fill();

            // Tail fin
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(-this.size * 0.3, -this.size * 0.5);
            ctx.lineTo(-this.size * 0.3, this.size * 0.5);
            ctx.closePath();
            ctx.fillStyle = this.color;
            ctx.fill();

            // Eye
            ctx.beginPath();
            ctx.arc(-this.size * 0.1, -this.size * 0.1, this.size * 0.15, 0, Math.PI * 2);
            ctx.fillStyle = '#fff';
            ctx.fill();

            ctx.restore();
        }
    }

    // Bubble class
    class Bubble {
        constructor() {
            this.x = Math.random() * width;
            this.y = height;
            this.size = Math.random() * 5 + 5;
            this.velocity = Math.random() * 2 + 1;
            this.alpha = 1;
        }

        update() {
            this.y -= this.velocity;
            this.size += 0.1;
            this.alpha -= 0.01;

            if (this.y < 0 || this.alpha <= 0) {
                return true;
            }
            return false;
        }

        draw() {
            ctx.beginPath();
            ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
            ctx.fillStyle = `rgba(255, 255, 255, ${this.alpha})`;
            ctx.fill();
        }
    }

    // Seaweed class
    class Seaweed {
        constructor() {
            this.x = Math.random() * width;
            this.y = height - 50;
            this.angle = Math.random() * Math.PI * 2;
            this.speed = Math.random() * 0.01 + 0.005;
        }

        update() {
            this.angle += this.speed;
        }

        draw() {
            ctx.save();
            ctx.translate(this.x, this.y);
            ctx.rotate(this.angle);

            // Stem
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(0, -30);
            ctx.lineTo(10, -20);
            ctx.lineTo(0, -10);
            ctx.closePath();
            ctx.fillStyle = '#228B22';
            ctx.fill();

            // Leaves
            ctx.beginPath();
            ctx.arc(0, -30, 10, 0, Math.PI * 2);
            ctx.fillStyle = '#3CB371';
            ctx.fill();

            ctx.restore();
        }
    }

    // Light ray class
    class LightRay {
        constructor() {
            this.x = Math.random() * width;
            this.y = Math.random() * height;
            this.angle = Math.random() * Math.PI * 2;
            this.length = Math.random() * 100 + 50;
            this.opacity = Math.random() * 0.3 + 0.2;
        }

        update() {
            this.y += Math.sin(this.angle) * 0.1;
            this.x += Math.cos(this.angle) * 0.1;
        }

        draw() {
            ctx.beginPath();
            ctx.moveTo(this.x, this.y);
            ctx.lineTo(this.x + Math.cos(this.angle) * this.length, 
                      this.y - Math.sin(this.angle) * this.length);
            ctx.strokeStyle = `rgba(255, 255, 255, ${this.opacity})`;
            ctx.lineWidth = 1;
            ctx.stroke();
        }
    }

    // Initialize objects
    const fish = [];
    for (let i = 0; i < 8; i++) {
        fish.push(new Fish());
    }

    const bubbles = [];
    const seaweeds = [];
    for (let i = 0; i < 20; i++) {
        seaweeds.push(new Seaweed());
    }

    const lightRays = [];
    for (let i = 0; i < 50; i++) {
        lightRays.push(new LightRay());
    }

    function animate(currentTime) {
        const delta = (currentTime - lastTime) / 1000;
        lastTime = currentTime;

        // Clear canvas
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, width, height);

        // Draw sandy bottom
        ctx.fillStyle = '#a0522d';
        ctx.fillRect(0, height - 50, width, 50);

        // Draw pebbles
        for (let i = 0; i < 50; i++) {
            ctx.beginPath();
            ctx.arc(Math.random() * width, height - 30, 2 + Math.random() * 3, 0, Math.PI * 2);
            ctx.fillStyle = '#8b4513';
            ctx.fill();
        }

        // Update and draw fish
        for (let fish of fish) {
            fish.update();
            fish.draw();
        }

        // Update and draw bubbles
        for (let i = bubbles.length - 1; i >= 0; i--) {
            if (bubbles[i].update()) {
                bubbles.splice(i, 1);
            } else {
                bubbles[i].draw();
            }
        }
        if (bubbles.length < 50) {
            bubbles.push(new Bubble());
        }

        // Update and draw seaweed
        for (let seaweed of seaweeds) {
            seaweed.update();
            seaweed.draw();
        }

        // Update and draw light rays
        for (let lightRay of lightRays) {
            lightRay.update();
            lightRay.draw();
        }

        requestAnimationFrame(animate);
    }

    requestAnimationFrame(animate);
</script>
</body>
</html>
